\u0021\u006a\u0042\u004b\u0060\u006a\u0058\u0078\u007c\u004d\u005b\u007e\u0070\u007d\u0042\u0064\u006e\u002c\u0042\u0076\u0065\u005c\u002a\u0023\u0066\u0073\u007e\u0032\u0030\u0063\u0065\u0059\u0065\u0040\u002f\u006f\u0038\u0055\u0021\u0054\u0030\u003a\u007a\u003c\u007e\u0060\u005e\u0030\u0042\u0046\u0047\u0032\u0043\u0040\u003f\u0061\u0020\u0031\u003f\u0021\u003d\u003f\u003e\u0037\u0054\u0054\u0051\u0026\u0065\u0066\u0070\u0031\u006a\u0042\u005f\u0035\u0072\u005c\u005a\u0055\u0020\u005b\u0065\u005f\u005b\u003b\u0047\u0059\u0054\u002c\u005f\u004a\u0079\u0058\u006d\u005f\u0073\u004e\u003a\u0029\u0056\u0078\u0052\u0042\u007e\u004a\u0067\u0036\u0045\u0040\u007e\u0023\u003e\u003d\u0044\u0073\u004a\u003a\u002a\u0046\u004c\u005e\u0074\u0025\u007a\u0070\u0079\u0069\u003d\u0051\u0020\u0063\u0053\u003b\u0039\u0066\u0075\u0064\u0061\u0059\u0063\u0021\u0035\u0070\u0022\u006c\u0042\u006e\u0037\u0046\u0052\u0049\u0059\u0021\u0049\u0039\u0025\u002a\u0043\u007a\u0039\u0030\u0029\u0048\u0035\u004e\u0034\u0037\u0067\u0023\u0042\u002f\u0043\u003b\u0023\u002a\u0029\u005a\u006a\u0025\u004c\u0043\u002a\u0041\u0067\u0069\u005f\u003a\u0046\u004b\u0027\u002b\u0056\u0073\u0057\u0039\u0028\u0077\u005e\u004d\u0036\u0022\u007b\u0027\u005c\u0055\u0077\u0046\u0071\u006a\u0034\u0029\u0079\u0054\u002b\u0050\u0045\u0025\u006b\u0021\u0073\u0024\u0077\u0069\u0054\u0032\u0034\u003c\u0025\u0041\u006b\u0045\u003a\u0031\u0067\u005f\u006b\u005b\u0056\u0060\u0034\u005e\u0068\u006e\u0048\u0052\u0070\u0032\u002a\u0020\u0050\u0057\u0050\u0076\u0034\u0076\u005b\u003b\u0066\u0071\u004e\u007d\u0064\u006a\u002f\u0079\u007d\u006e\u006d\u0078\u005e\u0075\u0045\u005f\u002a\u004e\u0076\u0037\u0059\u0027\u0036\u0021\u0030\u002e\u002a\u0021\u0033\u0058\u0033\u0044\u0029\u0020\u0035\u005c\u0050\u0022\u007e\u0038\u0065\u0074\u006f\u0023\u007e\u0028\u006f\u0064\u0057\u0062\u0063\u003f\u006b\u006e\u0065\u003f\u0061\u004b\u003d\u006a\u0053\u0027\u007d\u0047\u005e\u0064\u0059\u0024\u0058\u0037\u0079\u0027\u007c\u0028\u0048\u0049\u002c\u0025\u0072\u0049\u006f\u0058\u0027\u0078\u0047\u004a\u0073\u0031\u0030\u002a\u003c\u0056\u003b\u003d\u0050\u0060\u0025\u0059\u0020\u0050\u0028\u0061\u005f\u0052\u006d\u005d\u003e\u002f\u005a\u0033\u0072\u004f\u0074\u0035\u003c\u0055\u0078\u0024\u0023\u0060\u0037\u006f\u0063\u002b\u0068\u0042\u0049\u0023\u0061\u002c\u0057\u0033\u004d\u006d\u007e\u003c\u0060\u002c\u0078\u005c\u0046\u007d\u0078\u0028\u0051\u0032\u0053\u004e\u004d\u0039\u0055\u0030\u002f\u002b\u005a\u0067\u0052\u004e\u005b\u0078\u006b\u0066\u0053\u0072\u0072\u0032\u0059\u0050\u0071\u004f\u0073\u0033\u0059\u0040\u007b\u005d\u0046\u0056\u0020\u0025\u005c\u0037\u0061\u0041\u0044\u0032\u007d\u0059\u0075\u006d\u0041\u004b\u003a\u0054\u0053\u0067\u0030\u004d\u0073\u005d\u004d\u0041\u0061\u0046\u003b\u0062\u0051\u0038\u0026\u0072\u0036\u006f\u007e\u0068\u0053\u0044\u003c\u0027\u004c\u0053\u0068\u0021\u0028\u0055\u0072\u0078\u0025\u0072\u007c\u0023\u0054\u0045\u0037\u0029\u004e\u004a\u006c\u0045\u002b\u007d\u0026\u0071\u0031\u0033\u007a\u006a\u0060\u0057\u004a\u0027\u0023\u005c\u0025\u0049\u0025\u007e\u0031\u002a\u003a\u005f\u0048\u0033\u0026\u007d\u004a\u006f\u0027\u003a\u006d\u007e\u0052\u0060\u0043\u007e\u0069\u0021\u004e\u007b\u0043\u0068\u0071\u0079\u0062\u003a\u004a\u0031\u005b\u005c\u005e\u0021\u006c\u0051\u002a\u0050\u002f\u0032\u0034\u002b\u0044\u0074\u0029\u002e\u0028\u0053\u0077\u0041\u0061\u0045\u0066\u0056\u004d\u0070\u0079\u005b\u002b\u0048\u0076\u003e\u0034\u005b\u002e\u0043\u0065\u002a\u0076\u005a\u002e\u002f\u0048\u0064\u0032\u0028\u0067\u0073\u0071\u002c\u0046\u006f\u0068\u0069\u0029\u007c\u0051\u0041\u006e\u0073\u0066\u0036\u002c\u0075\u002a\u0045\u0021\u004d\u0031\u0071\u002d\u0042\u0023\u0037\u0049\u0025\u0045\u002a\u0076\u0037\u0078\u0060\u007a\u0037\u0076\u006d\u0068\u0076\u005b\u0077\u0034\u0063\u004d\u0054\u0064\u0074\u0060\u0024\u0035\u0064\u0021\u007a\u0030\u0045\u0076\u0047\u0059\u002d\u0045\u0028\u0057\u0034\u0058\u006a\u002b\u0060\u004a\u003a\u0031\u0064\u0024\u0030\u0035\u006f\u007c\u002f\u0046\u007a\u0023\u0043\u0032\u003e\u0049\u0069\u006f\u0051\u0077\u002d\u002b\u0075\u0021\u002e\u0074\u0044\u0060\u0043\u0061\u0056\u005b\u0033\u005b\u003a\u0052\u007c\u006a\u003c\u004e\u0079\u003b\u0050\u0055\u0046\u006b\u0073\u0065\u002c\u0037\u005a\u0049\u005a\u0069\u005b\u0064\u0038\u002a\u003c\u004c\u005e\u0075\u0074\u005b\u003d\u0074\u002d\u006f\u002d\u0048\u0040\u003b\u0064\u0066\u0061\u005c\u0023\u0069\u004e\u005a\u0050\u0035\u006d\u002a\u0056\u004d\u002c\u0078\u006b\u002e\u0047\u0059\u0031\u0074\u0049\u0066\u0048\u0024\u007c\u007c\u0075\u0027\u004d\u0021\u0035\u0049\u0056\u0072\u003e\u006d\u0036\u007a\u0050\u006e\u005d\u005d\u006b\u0038\u007b\u005f\u006d\u006c\u0055\u006a\u006f\u0033\u0045\u0075\u0025\u004d\u006d\u0070\u0043\u0028\u006c\u005f\u004b\u0049\u005f\u005b\u002e\u003c\u0034\u0059\u0053\u0048\u0026\u005a\u006d\u0023\u006a\u0049\u0049\u0055\u006e\u0060\u0042\u007e\u003f\u0036\u0022\u0030\u005c\u004e\u0037\u0052\u0067\u0072\u0062\u0022\u003a\u0023\u007a\u004a\u0054\u002a\u0032\u006f\u0034\u0047\u003d\u005b\u007e\u003c\u005c\u0023\u0059\u007a\u005f\u003e\u005b\u0024\u005e\u0057\u0055\u005c\u007a\u0046\u0021\u002b\u007d\u004b\u0030\u0062\u0028\u004d\u0063\u0027\u004b\u0064\u0031\u0033\u0065\u0035\u0079\u006e\u0020\u0076\u005f\u0023\u0067\u0063\u0027\u003f\u0022\u0025\u0020\u0071\u0049\u0058\u006f\u003d\u003a\u0041\u0058\u007e\u002b\u0057\u007a\u0031\u0072\u004b\u0046\u0027\u0052\u0061\u007d\u0033\u002e\u004e\u0073\u003a\u002b\u0046\u0023\u007c\u0064\u0068\u0038\u0033\u0028\u004b\u006a\u002f\u0068\u0053\u0066\u0057\u0045\u0065\u002d\u0036\u0041\u0025\u0046\u0074\u004c\u0029\u0044\u0053\u007b\u005d\u006d\u0040\u002f\u0029\u0074\u0038\u0044\u0047\u0039\u005a\u004a\u0075\u0072\u0074\u0024\u0077\u0051\u0020\u0028\u0042\u004c\u006a\u0062\u0021\u0062\u006a\u0071\u003c\u007a\u0040\u0030\u0052\u0072\u0043\u0071\u0059\u0020\u0021\u004d\u0062\u0065\u0069\u005e\u0031\u006f\u0041\u0041\u0059\u0048\u0031\u004a\u004e\u0041\u0052\u0052\u003e\u0040\u005e\u0047\u0030\u0034\u0073\u0058\u005f\u004c\u0073\u0021\u002d\u0037\u0035\u0032\u005b\u0037\u0028\u0029\u003b\u002f\u0071\u0034\u004c\u0021\u0029\u003b\u0056\u006d\u0060\u0048\u007c\u0078\u006e\u003e\u0052\u005c\u005e\u0021\u0024\u0071\u0054\u0037\u0066\u005c\u0065\u0050\u002c\u0064\u005c\u0022\u0060\u0026\u0057\u002d\u006e\u0050\u0079\u003c\u0045\u006a\u003e\u0071\u0040\u0070\u0050\u0025\u0069\u0041\u0033\u0074\u0077\u006f\u003f\u005f\u0078\u0023\u005c\u006b\u0045\u0078\u003f\u005f\u003d\u0036\u006f\u007d\u0062\u007d\u0046\u0074\u004d\u0079\u0079\u0020\u0052\u0031\u0028\u007b\u006b\u0054\u003c\u0048\u0058\u0038\u0062\u005f\u003f\u004d\u004b\u0076\u0065\u0037\u0071\u0063\u004f\u0063\u0067\u003d\u0061\u0058\u0079\u0073\u003e\u0039\u0062\u0048\u005e\u003d\u0079\u0053\u006c\u004e\u0027\u007a\u006e\u0038\u0068\u0066\u006b\u0077\u002d\u0076\u0026\u0042\u005e\u0058\u0061\u004c\u0051\u005b\u0020\u0046\u0029\u0027\u0038\u0072\u0026\u0029\u002e\u005d\u0022\u0059\u0032\u0043\u007c\u002d\u0070\u0053\u0057\u007b\u0020\u002e\u0066\u0042\u002e\u004c\u003a\u007d\u0056\u0057\u0023\u007a\u003c\u0051\u0042\u0069\u0021\u0026\u0027\u0076\u0076\u003b\u0032\u003d\u0039\u0057\u0065\u003d\u002a\u006e\u0059\u006a\u005c\u0052\u006a\u0043\u0023\u0039\u004b\u0076\u005a\u0034\u0065\u007b\u006f\u0055\u003c\u007e\u0031\u0062\u0052\u0034\u0033\u006c\u004b\u0070\u003a\u0041\u005e\u0072\u006b\u0031\u0055\u0050\u0074\u0028\u0063\u005e\u005d\u0029\u007e\u0079\u003c\u006a\u0077\u0053\u005e\u006f\u002c\u004c\u0052\u0044\u0044\u0036\u0046\u0040\u0023\u007b\u002c\u0059\u007c\u0070\u0025\u0034\u0048\u0061\u0043\u002d\u004a\u006b\u005d\u0029\u003e\u0032\u003d\u0022\u002d\u005c\u005c\u002e\u002c\u0064\u0050\u0036\u0061\u002e\u006c\u0038\u0052\u0046\u002c\u0030\u0051\u0048\u0051\u0031\u0066\u004f\u0057\u0063\u003d\u005d\u006f\u0073\u007b\u004a\u0023\u0075\u007a\u0048\u0034\u0070\u0068\u0038\u0057\u0030\u0069\u0061\u002d\u0023\u0071\u0043\u0069\u0036\u0051\u0027\u005c\u006f\u002b\u005e\u0042\u0062\u0054\u004b\u002b\u004d\u005b\u0067\u0077\u0035\u0037\u005e\u003b\u007b\u007a\u0034\u004e\u005f\u003e\u003a\u006c\u0051\u0041\u0067\u0052\u0076\u006c\u0031\u004f\u002c\u0037\u002b\u0047\u004c\u006b\u007d\u002d\u004a\u0071\u0044\u0052\u0027\u0076\u0044\u0047\u0023\u0066\u002c\u006c\u0062\u004f\u004b\u0073\u002c\u0052\u003f\u004a\u006f\u006a\u0029\u0030\u007a\u0030\u007a\u0050\u0039\u0037\u0046\u0065\u0043\u007d\u0057\u007a\u0070\u0064\u0029\u002d\u005f\u0021\u0049\u0024\u006d\u0033\u0052\u0065\u0055\u0068\u0041\u0040\u0043\u0055\u0041\u0058\u0028\u006b\u0056\u0047\u0047\u0024\u004a\u004b\u0079\u0022\u0041\u0056\u0028\u0047\u0071\u0072\u0069\u0043\u0078\u007e\u0079\u006b\u0068\u0023\u0033\u0031\u007b\u0053\u0029\u0034\u005d\u0062\u0057\u004a\u0035\u0072\u0043\u0038\u0046\u0053\u0024\u0046\u0073\u004d\u005e\u0059\u005c\u004c\u007d\u0053\u0036\u0031\u002d\u0043\u002c\u0073\u0034\u0040\u0029\u007d\u0048\u0036\u0052\u002e\u002c\u0058\u0054\u0021\u0067\u0069\u0051\u0041\u003a\u004e\u0069\u0053\u0065\u0065\u006f\u0070\u002f\u003c\u0026\u0030\u003f\u006f\u004f\u004d\u0078\u0042\u004e\u0073\u0039\u007e\u0024\u0077\u005a\u0033\u0030\u004c\u0052\u0044\u005f\u0022\u0063\u007e\u0025\u0077\u006d\u007d\u002b\u0055\u004f\u007a\u0053\u006e\u0063\u0070\u0056\u0053\u0048\u0035\u0071\u003b\u0033\u0057\u0042\u0048\u0028\u002a\u0078\u0041\u0046\u0060\u005e\u003f\u0031\u0023\u006a\u0039\u002e\u006c\u0078\u0036\u004a\u0056\u006c\u0063\u0052\u002e\u004b\u003e\u0079\u007e\u0073\u0027\u0068\u0020\u005f\u004e\u004f\u005c\u006d\u0079\u0046\u0047\u0074\u003c\u0071\u0039\u0053\u0071\u0037\u0065\u003e\u0079\u0024\u004b\u0049\u0029\u0061\u002f\u0064\u0064\u0037\u0074\u0078\u005f\u004b\u0067\u007b\u0066\u0067\u0070\u0074\u0039\u006d\u0040\u0052\u003b\u0076\u0065\u002e\u0064\u0066\u0035\u006c\u0079\u0056\u0075\u0070\u006c\u0061\u0050\u005e\u0075\u0032\u0040\u0043\u003d\u0031\u0038\u0050\u0065\u0026\u0062\u005f\u004a\u007e\u0032\u006f\u0070\u0030\u007e\u0035\u0039\u002c\u003b\u005d\u004e\u0054\u0053\u0022\u006b\u007c\u003e\u0071\u0024\u0051\u0021\u0020\u0045\u0049\u0046\u003b\u0028\u0079\u002a\u005c\u0057\u0079\u006c\u0022\u0026\u0077\u0052\u0036\u007a\u0041\u0033\u0020\u0071\u0040\u0044\u005b\u0066\u0070\u0035\u0077\u0047\u0070\u0058\u0020\u006e\u0057\u0047\u006e\u0066\u0049\u0046\u0028\u0032\u0024\u0020\u002a\u0029\u004a\u004e\u0060\u002a\u0071\u006d\u005d\u005b\u0079\u007b\u0068\u0033\u0056\u0056\u0027\u006e\u007e\u0029\u0021\u002a\u0073\u0035\u0033\u0060\u0041\u0045\u006c\u0032\u0061\u007b\u005f\u007a\u007d\u0020\u0060\u0023\u006c\u002c\u0059\u0045\u0052\u0066\u003d\u0027\u0073\u006a\u0024\u0066\u0028\u007b\u0027\u0075\u0024\u0068\u0061\u002a\u0056\u0022\u0064\u0029\u0036\u006a\u005c\u0022\u0027\u006c\u006b\u0066\u004a\u0057\u005e\u0054\u0056\u0026\u0024\u0069\u0033\u006b\u006c\u0052\u006e\u005a\u0031\u0059\u003c\u0073\u007c\u0063\u0026\u0066\u003b\u002e\u0078\u004d\u0034\u0021\u0063\u0073\u0045\u004e\u0076\u005e\u0041\u0044\u003f\u0030\u004a\u007a\u0052\u0042\u005d\u0045\u0072\u0034\u0032\u0025\u006f\u0058\u006a\u0039\u004e\u0026\u0041\u004c\u0053\u0042\u007b\u004d\u004c\u007a\u0046\u0071\u0074\u0079\u0069\u0063\u003a\u0068\u0029\u0078\u005e\u0069\u0027\u0053\u002f\u0049\u0055\u0048\u004c\u003a\u003b\u0058\u0078\u0035\u0031\u002e\u0021\u0048\u0030\u0044\u007d\u0072\u007e\u0059\u006e\u0052\u007d\u0067\u0069\u0073\u0026\u005d\u007d\u0022\u003e\u005d\u005a\u0024\u0031\u004f\u0032\u0044\u0030\u005c\u0027\u004f\u0058\u006d\u0075\u0076\u0024\u0045\u0068\u0023\u0075\u0030\u007d\u003f\u0046\u004c\u0032\u007b\u003c\u0073\u0064\u0029\u003f\u007b\u0074\u0042\u003e\u002d\u005a\u004e\u003a\u0057\u0064\u003f\u0048\u0077\u0071\u003b\u0044\u007c\u0045\u0062\u0038\u0071\u004c\u0036\u0063\u0050\u0027\u005a\u0070\u0044\u0040\u0036\u0050\u004b\u0056\u003a\u0052\u003e\u0060\u0036\u0042\u0024\u004e\u005b\u0056\u004c\u0034\u0076\u0022\u002b\u005b\u0045\u0074\u0062\u006e\u002d\u004d\u003f\u0053\u0064\u0033\u003f\u003e\u0022\u0044\u0074\u0031\u0045\u0047\u0043\u002e\u0056\u0057\u0068\u0050